const messageText = $input.first().json.message.text;
const chatId = $input.first().json.message.chat.id;
const urlRegex = /(https?:\/\/[^\s]+)/g;
const matches = messageText.match(urlRegex);
if (!matches || matches.length === 0) {
  return [{
    json: {
      error: true,
      chatId: chatId,
      message: "⚠️ Please provide a valid URL.\n\nUsage: /learn https://example.com/article"
    }
  }];
}
return [{
  json: {
    error: false,
    url: matches[0],
    chatId: chatId,
    materialId: 'LM-' + Date.now()
  }
}];

const html = $input.first().json.data || '';
const prevData = $('Extract URL').first().json;
if (!html || html.length < 100) {
  return [{
    json: {
      ...prevData,
      content: '',
      contentReady: false,
      message: "⚠️ Could not fetch content from this URL. The page might be empty or blocked.\n\nTry a different URL."
    }
  }];
}
let text = html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '')
  .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '')
  .replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ')
  .trim();
if (text.length > 30000) {
  text = text.substring(0, 30000) + '\n\n[Content truncated]';
}
return [{
  json: {
    ...prevData,
    content: text,
    contentReady: text.length >= 100
  }
}];

const rawContent = $input.first().json.data;
const prevData = $('Extract URL').first().json;
let content = rawContent
  .replace(/!\[.*?\]\(.*?\)/g, '')
  .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1')
  .replace(/#{1,6}\s*/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
if (content.length > 30000) {
  content = content.substring(0, 30000) + '\n\n[Content truncated]';
}
return [{
  json: {
    ...prevData,
    content: content,
    contentReady: true
  }
}];

const raw = $input.first().json;
const aiResponse = raw.text || raw.response || raw.output || raw.message?.content || '';
const prevData = {
  ...$('Extract URL').first().json,
  content: $('Content Ready?').first().json.content
};
let parsed;
try {
  const clean = aiResponse
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    title: "Untitled Material",
    difficulty: "intermediate",
    summary: aiResponse.substring(0, 300),
    keyPoints: ["Could not parse structured summary."],
    mainConcepts: ["general"]
  };
}

// Escape HTML special chars in AI-generated content (e.g. JSX tags like <button/>)
const escapeHtml = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
};
parsed.title = escapeHtml(parsed.title);
parsed.summary = escapeHtml(parsed.summary);
parsed.keyPoints = parsed.keyPoints.map(p => escapeHtml(p));
parsed.mainConcepts = parsed.mainConcepts.map(c => escapeHtml(c));

// Format with HTML tags (NOT Markdown — safe from AI-generated special chars)
const keyPointsList = parsed.keyPoints
  .map((p, i) => `  ${i + 1}. ${p}`)
  .join('\n');
const conceptsList = parsed.mainConcepts.join(', ');
const telegramMessage =
  `📚 <b>${parsed.title}</b>\n\n` +
  `📊 <b>Difficulty:</b> ${parsed.difficulty}\n\n` +
  `📝 <b>Summary:</b>\n${parsed.summary}\n\n` +
  `🔑 <b>Key Points:</b>\n${keyPointsList}\n\n` +
  `💡 <b>Main Concepts:</b> ${conceptsList}\n\n` +
  `✅ Material saved! Take a quiz now or use /quiz later.`;

// Inline keyboard: "Take Quiz Now" button
const replyMarkup = [
  [
    {
      text: "📝 Take Quiz Now",
      callback_data: `topic_${prevData.materialId}`
    }
  ]
];
return [{
  json: {
    materialId: prevData.materialId,
    chatId: prevData.chatId,
    url: prevData.url,
    title: parsed.title,
    content: prevData.content,
    summary: JSON.stringify(parsed),
    difficulty: parsed.difficulty,
    telegramMessage: telegramMessage,
    replyMarkup: replyMarkup,
    addedDate: new Date().toISOString()
  }
}];

const items = $input.all();
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const userMaterials = items.filter(item =>
  String(item.json.chatId) === String(chatId)
);
if (userMaterials.length === 0) {
  return [{
    json: {
      chatId: chatId,
      hasTopics: false,
      message: "📭 You haven't saved any materials yet!\n\nUse /learn <url> to add your first topic."
    }
  }];
}
// Build inline keyboard — one button per material
// Format: array of rows, each row is array of button objects
const replyMarkup = userMaterials.map(item => [{
  text: `📖 ${item.json.title || 'Untitled'} (${item.json.difficulty || '?'})`,
  callback_data: `topic_${item.json.id}`
}]);
return [{
  json: {
    chatId: chatId,
    hasTopics: true,
    message: "📝 Choose a topic for your quiz:",
    replyMarkup: replyMarkup
  }
}];

const callback = $input.first().json.callback_query;
const materialId = callback.data.replace('topic_', '');
const chatId = callback.message.chat.id;
const callbackQueryId = callback.id;
const messageId = callback.message.message_id;
return [{
  json: { materialId, chatId, callbackQueryId, messageId }
}];

const items = $input.all();
const materialId = $('Extract Topic ID').first().json.materialId;
const chatId = $('Extract Topic ID').first().json.chatId;
const material = items.find(item => item.json.id === materialId);
if (!material) {
  return [{
    json: {
      error: true,
      chatId: chatId,
      message: "❌ Material not found. Please try /quiz again."
    }
  }];
}
return [{
  json: {
    error: false,
    materialId: material.json.id,
    chatId: chatId,
    title: material.json.title,
    content: material.json.content,
    summary: material.json.summary
  }
}];

const raw = $input.first().json;
const aiResponse = raw.text || raw.response || raw.output || '';
const prevData = $('Find Selected Material').first().json;
const sessionId = 'QS-' + Date.now();
let questions;
try {
  const clean = aiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  questions = JSON.parse(clean);
} catch (e) {
  return [{
    json: {
      error: true,
      chatId: prevData.chatId,
      message: "❌ Failed to generate quiz. Please try /quiz again."
    }
  }];
}
if (!Array.isArray(questions) || questions.length === 0) {
  return [{
    json: {
      error: true,
      chatId: prevData.chatId,
      message: "❌ AI generated invalid quiz data. Please try /quiz again."
    }
  }];
}
// Build inline keyboard for FIRST question
const q = questions[0];
const replyMarkup = Object.entries(q.options).map(([key, value]) => [{
  text: `${key}) ${value.length > 55 ? value.substring(0, 55) + '...' : value}`,
  callback_data: `answer_${sessionId}_0_${key}`
}]);
// HTML formatted message
const messageText =
  `📝 <b>Quiz: ${prevData.title}</b>\n\n` +
  `<b>Question 1/${questions.length}:</b>\n${q.question}`;
return [{
  json: {
    error: false,
    sessionId: sessionId,
    chatId: prevData.chatId,
    materialId: prevData.materialId,
    title: prevData.title,
    content: prevData.content,
    questions: JSON.stringify(questions),
    totalQuestions: questions.length,
    messageText: messageText,
    replyMarkup: replyMarkup
  }
}];

const callback = $input.first().json.callback_query;
const data = callback.data;
// Format: answer_{sessionId}_{questionIndex}_{answerLetter}
const parts = data.split('_');
const sessionId = parts[1];
const questionIndex = parseInt(parts[2]);
const userAnswer = parts[3];
const chatId = callback.message.chat.id;
const callbackQueryId = callback.id;
const messageId = callback.message.message_id;
return [{
  json: { sessionId, questionIndex, userAnswer, chatId, callbackQueryId, messageId }
}];

const existingAnswers = $input.all();
const answerData = $('Parse Answer Callback').first().json;

// Filter only real sheet rows (they have sessionId but no callbackQueryId)
const sheetAnswers = existingAnswers.filter(item => 
  item.json.sessionId && 
  item.json.questionIndex !== undefined &&
  !item.json.callbackQueryId
);

const isDuplicate = sheetAnswers.some(item =>
  item.json.sessionId === answerData.sessionId &&
  String(item.json.questionIndex) === String(answerData.questionIndex)
);

return [{
  json: { ...answerData, isDuplicate }
}];

const sessions = $input.all();
const answerData = $('Check Duplicate').first().json;
const session = sessions.find(s => s.json.sessionId === answerData.sessionId);
if (!session) {
  return [{
    json: {
      error: true,
      chatId: answerData.chatId,
      message: "❌ Quiz session not found. Start a new quiz with /quiz."
    }
  }];
}
const questions = JSON.parse(session.json.questions);
const currentQ = questions[answerData.questionIndex];
const nextIndex = answerData.questionIndex + 1;
const isLastQuestion = nextIndex >= questions.length;
// Deterministic check — reliable, no hallucination risk
const isCorrect = answerData.userAnswer === currentQ.correctAnswer;
return [{
  json: {
    error: false,
    chatId: answerData.chatId,
    sessionId: answerData.sessionId,
    questionIndex: answerData.questionIndex,
    userAnswer: answerData.userAnswer,
    correctAnswer: currentQ.correctAnswer,
    isCorrect: isCorrect,
    questionText: currentQ.question,
    questionOptions: JSON.stringify(currentQ.options),
    isLastQuestion: isLastQuestion,
    nextIndex: nextIndex,
    totalQuestions: questions.length,
    questions: session.json.questions
  }
}];

const raw = $input.first().json;
const aiResponse = raw.text || raw.response || raw.output || '';
const prevData = $('Find Session & Extract Question').first().json;

// Escape HTML in AI-generated text
const escapeHtml = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
};

let validation;
try {
  const clean = aiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  validation = JSON.parse(clean);
} catch (e) {
  validation = {
    isCorrect: prevData.isCorrect,
    feedback: prevData.isCorrect
      ? "Correct!"
      : `The correct answer was ${prevData.correctAnswer}.`
  };
}
const isCorrect = prevData.isCorrect;
const feedback = validation.feedback || (isCorrect ? "Correct!" : "Incorrect.");

// HTML formatted feedback
let resultMessage = '';
if (isCorrect) {
  resultMessage = `✅ ${escapeHtml(feedback)}\n\n`;
} else {
  resultMessage = `❌ <b>Correct answer: ${prevData.correctAnswer}</b>\n💡 ${escapeHtml(feedback)}\n\n`;
}

// Prepare next question if not last
let replyMarkup = null;
if (!prevData.isLastQuestion) {
  const questions = JSON.parse(prevData.questions);
  const nextQ = questions[prevData.nextIndex];
  replyMarkup = Object.entries(nextQ.options).map(([key, value]) => [{
    text: `${key}) ${value.length > 55 ? value.substring(0, 55) + '...' : value}`,
    callback_data: `answer_${prevData.sessionId}_${prevData.nextIndex}_${key}`
  }]);
  resultMessage += `<b>Question ${prevData.nextIndex + 1}/${prevData.totalQuestions}:</b>\n${escapeHtml(nextQ.question)}`;
}

return [{
  json: {
    chatId: prevData.chatId,
    sessionId: prevData.sessionId,
    questionIndex: prevData.questionIndex,
    userAnswer: prevData.userAnswer,
    correctAnswer: prevData.correctAnswer,
    isCorrect: isCorrect,
    explanation: escapeHtml(feedback),
    isLastQuestion: prevData.isLastQuestion,
    message: resultMessage,
    replyMarkup: replyMarkup,
    questions: prevData.questions,
    totalQuestions: prevData.totalQuestions
  }
}];

const allAnswers = $input.all();
const prevData = $('Parse Validation & Prepare Next').first().json;
const sessionId = prevData.sessionId;

// Escape HTML in AI-generated text to prevent Telegram parse errors
const escapeHtml = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
};

const sessionAnswers = allAnswers
  .filter(a => a.json.sessionId === sessionId)
  .sort((a, b) => parseInt(a.json.questionIndex) - parseInt(b.json.questionIndex));
let correctCount = sessionAnswers.filter(a =>
  a.json.isCorrect === true || a.json.isCorrect === 'true'
).length;
const lastInSheets = sessionAnswers.some(a =>
  String(a.json.questionIndex) === String(prevData.questionIndex)
);
if (!lastInSheets && prevData.isCorrect) correctCount++;
const totalQuestions = prevData.totalQuestions || 5;
const scorePercent = Math.round((correctCount / totalQuestions) * 100);
let emoji = '📖';
if (scorePercent >= 90) emoji = '🏆';
else if (scorePercent >= 70) emoji = '🌟';
else if (scorePercent >= 40) emoji = '💪';

let incorrectFeedback = '';
for (const ans of sessionAnswers) {
  if (ans.json.isCorrect === false || ans.json.isCorrect === 'false') {
    const qIdx = parseInt(ans.json.questionIndex) + 1;
    incorrectFeedback += `\n❌ <b>Q${qIdx}:</b> Correct: ${ans.json.correctAnswer}\n💡 ${escapeHtml(ans.json.explanation)}\n`;
  }
}
if (!lastInSheets && !prevData.isCorrect) {
  incorrectFeedback += `\n❌ <b>Q${prevData.questionIndex + 1}:</b> Correct: ${prevData.correctAnswer}\n💡 ${escapeHtml(prevData.explanation)}\n`;
}
const lastFeedback = prevData.isCorrect
  ? `✅ ${escapeHtml(prevData.explanation)}\n\n`
  : `❌ <b>Correct answer: ${prevData.correctAnswer}</b>\n💡 ${escapeHtml(prevData.explanation)}\n\n`;

const message =
  lastFeedback +
  `━━━━━━━━━━━━━━━━━━\n` +
  `${emoji} <b>Quiz Complete!</b>\n\n` +
  `📊 <b>Your Score: ${correctCount}/${totalQuestions} (${scorePercent}%)</b>\n` +
  (incorrectFeedback
    ? `\n📋 <b>Review incorrect answers:</b>${incorrectFeedback}`
    : '\n🎯 <b>Perfect score! Outstanding!</b>') +
  `\n\n📚 /learn — add new material\n📝 /quiz — try another topic`;
return [{
  json: { chatId: prevData.chatId, message }
}];

